function guessLiquidacion(text) {
  if (!text) return null;
  const liq = parseLiquidacion(text);
  if (liq.kg == null && liq.price == null && !liq.discounts.length && liq.gross == null && liq.net == null) {
    return null;
  }
  return {
    product: liq.product,
    category: liq.category,
    kg: liq.kg,
    price: liq.price,
    discounts: liq.discounts,
    notes: liq.notes,
  };
}

